CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY, room TEXT NOT NULL CHECK(room IN ('family','parents')), author TEXT NOT NULL, content TEXT NOT NULL, created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS message_room_time ON messages(room,created);
CREATE TABLE IF NOT EXISTS approvals(id TEXT PRIMARY KEY, room TEXT NOT NULL, author TEXT NOT NULL, proposal TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending', decided_by TEXT, created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS usage(day TEXT PRIMARY KEY, calls INTEGER NOT NULL);
